const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const UPLOAD_DIR = path.resolve('/var/uploads');
const MAX_FILE_SIZE = 1024 * 1024;
const ALLOWED_EXTENSIONS = new Set(['.txt', '.png', '.jpg', '.pdf', '.doc']);

// Security: Validate that resolved path is within upload directory
function isPathSafe(targetPath) {
  const resolved = path.resolve(targetPath);
  return resolved.startsWith(UPLOAD_DIR + path.sep) || resolved === UPLOAD_DIR;
}

// Security: Sanitize filename - only allow safe characters
function sanitizeFilename(name) {
  if (!name || typeof name !== 'string') return null;
  // Strip to basename first to remove any directory components
  let clean = path.basename(name);
  // Remove null bytes and control characters
  clean = clean.replace(/[\x00-\x1f\x7f]/g, '');
  // Only allow alphanumeric, dash, underscore, dot
  clean = clean.replace(/[^a-zA-Z0-9._-]/g, '');
  // Prevent hidden files and double dots
  clean = clean.replace(/^\.+/, '');
  clean = clean.replace(/\.\./g, '');
  // Must have content remaining
  if (!clean || clean.length === 0 || clean.length > 255) return null;
  return clean;
}

// Security: Check file extension against allowlist
function hasAllowedExtension(filename) {
  const ext = path.extname(filename).toLowerCase();
  return ALLOWED_EXTENSIONS.has(ext);
}

// NOTE: This function looks dangerous but is NEVER called from any request handler.
// It exists only for offline batch processing invoked by a trusted cron job.
// Included here because it's part of the same module file.
function _internalBatchTransform(trustedConfigPath) {
  // Only reads from a hardcoded trusted config directory
  const configDir = '/etc/app/transforms/';
  const resolved = path.resolve(configDir, path.basename(trustedConfigPath));
  if (!resolved.startsWith(configDir)) return null;
  // This would be called by cron with trusted input only
  return resolved;
}

class FileUploadHandler {
  constructor() {
    this.sessions = new Map();
  }

  authenticate(req) {
    const token = req.headers['x-auth-token'];
    if (!token || typeof token !== 'string' || token.length !== 64) return null;
    if (!/^[a-f0-9]{64}$/.test(token)) return null;
    return this.sessions.get(token) || null;
  }

  async handleUpload(req, res) {
    const user = this.authenticate(req);
    if (!user) { res.writeHead(401); res.end('Unauthorized'); return; }

    const chunks = [];
    let size = 0;
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX_FILE_SIZE) { res.writeHead(413); res.end('Too large'); return; }
      chunks.push(chunk);
    }
    const body = Buffer.concat(chunks);

    let metadata;
    try { metadata = JSON.parse(req.headers['x-file-metadata'] || '{}'); }
    catch { res.writeHead(400); res.end('Invalid metadata'); return; }

    const rawFilename = metadata.filename;
    const sanitized = sanitizeFilename(rawFilename);
    if (!sanitized) {
      res.writeHead(400); res.end('Invalid filename'); return;
    }

    if (!hasAllowedExtension(sanitized)) {
      res.writeHead(400); res.end('Extension not allowed'); return;
    }

    // Construct final path
    const userDir = path.join(UPLOAD_DIR, user.id);
    const finalPath = path.join(userDir, sanitized);

    // Final safety: verify resolved path is within upload dir
    if (!isPathSafe(finalPath)) {
      res.writeHead(400); res.end('Path traversal detected'); return;
    }

    await fs.promises.mkdir(userDir, { recursive: true });
    await fs.promises.writeFile(finalPath, body);

    res.writeHead(200, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({status: 'ok', path: `/files/${user.id}/${sanitized}`}));
  }

  handleDownload(req, res) {
    const user = this.authenticate(req);
    if (!user) { res.writeHead(401); res.end('Unauthorized'); return; }

    const url = new URL(req.url, 'http://localhost');
    const requestedFile = url.searchParams.get('file');
    const sanitized = sanitizeFilename(requestedFile);
    if (!sanitized) { res.writeHead(400); res.end('Invalid file param'); return; }

    const userDir = path.join(UPLOAD_DIR, user.id);
    const filePath = path.join(userDir, sanitized);

    // Verify path is within user's upload directory
    if (!isPathSafe(filePath)) {
      res.writeHead(403); res.end('Access denied'); return;
    }

    fs.readFile(filePath, (err, data) => {
      if (err) { res.writeHead(404); res.end('Not found'); return; }
      res.writeHead(200); res.end(data);
    });
  }

  handleLogin(req, res) {
    const chunks = [];
    let size = 0;
    req.on('data', c => {
      size += c.length;
      if (size > 4096) { req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      try {
        const {username, password} = JSON.parse(Buffer.concat(chunks).toString());
        if (username && typeof username === 'string' && password && typeof password === 'string' && password.length >= 8) {
          const token = crypto.randomBytes(32).toString('hex');
          const userId = username.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32);
          if (!userId) { res.writeHead(400); res.end('Invalid username'); return; }
          this.sessions.set(token, {id: userId, username: userId});
          res.writeHead(200, {'Content-Type': 'application/json'});
          res.end(JSON.stringify({token}));
        } else {
          res.writeHead(401); res.end('Invalid credentials');
        }
      } catch { res.writeHead(400); res.end('Bad request'); }
    });
  }
}

const handler = new FileUploadHandler();
const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/upload') handler.handleUpload(req, res);
  else if (req.method === 'GET' && req.url.startsWith('/download')) handler.handleDownload(req, res);
  else if (req.method === 'POST' && req.url === '/login') handler.handleLogin(req, res);
  else { res.writeHead(404); res.end('Not found'); }
});

server.listen(3000, '127.0.0.1');
